    "home.logos.countries": {en:"Countries served",zh:"服务国家",es:"Países atendidos",ru:"Стран обслужено",ar:"دولة تم خدمتها",tr:"Ülkeye hizmet",fr:"Pays desservis",pt:"Países atendidos",hi:"देशों में सेवा",id:"Negara dilayani"},
