    "case.vietnam.config.li1": {en:"<strong>Coil width:</strong> up to 1,250&nbsp;mm (the U version)",zh:"<strong>卷材宽度：</strong>最大1,250&nbsp;mm（U版本）",es:"<strong>Ancho de bobina:</strong> hasta 1,250&nbsp;mm (el U version)",ru:"<strong>Ширина рулона:</strong> до 1,250&nbsp;mm (the U version)",ar:"<strong>عرض اللفة:</strong> حتى 1,250&nbsp;mm (the U version)",tr:"<strong>Bobin genişliği:</strong> kadar 1,250&nbsp;mm (the U version)",fr:"<strong>Largeur de bobine:</strong> jusqu'à 1,250&nbsp;mm (le U version)",pt:"<strong>Largura da bobina:</strong> até 1,250&nbsp;mm (o U version)",hi:"<strong>कॉइल चौड़ाई:</strong> तक 1,250&nbsp;mm (the U version)",id:"<strong>Lebar koil:</strong> hingga 1,250&nbsp;mm (the U version)"},
    "case.vietnam.config.li2": {en:"<strong>Material:</strong> galvanised steel GI 0.5&ndash;1.0&nbsp;mm",zh:"<strong>材料：</strong>镀锌钢GI 0.5&ndash;1.0&nbsp;mm",es:"<strong>Material:</strong> acero galvanizado GI 0.5&ndash;1.0&nbsp;mm",ru:"<strong>Материал:</strong> оцинкованная сталь GI 0.5&ndash;1.0&nbsp;mm",ar:"<strong>مادة:</strong> فولاذ مجلفن GI 0.5&ndash;1.0&nbsp;mm",tr:"<strong>Malzeme:</strong> galvanizli çelik GI 0.5&ndash;1.0&nbsp;mm",fr:"<strong>Matériau:</strong> acier galvanisé GI 0.5&ndash;1.0&nbsp;mm",pt:"<strong>Material:</strong> aço galvanizado GI 0.5&ndash;1.0&nbsp;mm",hi:"<strong>सामग्री:</strong> गैल्वनाइज्ड स्टील GI 0.5&ndash;1.0&nbsp;mm",id:"<strong>Material:</strong> baja galvanis GI 0.5&ndash;1.0&nbsp;mm"},
    "case.vietnam.config.li3": {en:"<strong>Seam:</strong> integrated Pittsburgh lock forming, with S-cleat and drive cleat options",zh:"<strong>咬口：</strong>集成匹兹堡锁成型，可选S型扣件和驱动扣件",es:"<strong>Seam:</strong> integrated cierre Pittsburgh forming, con S-cleat y drive cleat options",ru:"<strong>Seam:</strong> integrated питтсбургский замок forming, с S-cleat и drive cleat options",ar:"<strong>Seam:</strong> integrated قفل بيتسبرغ forming, مع S-cleat و drive cleat options",tr:"<strong>Seam:</strong> integrated Pittsburgh kilit forming, ile S-cleat ve drive cleat options",fr:"<strong>Seam:</strong> integrated agrafage Pittsburgh forming, avec S-cleat et drive cleat options",pt:"<strong>Seam:</strong> integrated fechamento Pittsburgh forming, com S-cleat e drive cleat options",hi:"<strong>Seam:</strong> integrated पिट्सबर्ग लॉक forming, के साथ S-cleat और drive cleat options",id:"<strong>Seam:</strong> integrated kunci Pittsburgh forming, dengan S-cleat dan drive cleat options"},
    "case.vietnam.config.li4": {en:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/day on a single shift at the buyer&apos;s site; 2,500&nbsp;m&sup2;/day rated on two shifts",zh:"<strong>目标产量：</strong>在买方现场单班1,200&nbsp;m&sup2;/天；双班额定2,500&nbsp;m&sup2;/天",es:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/día en un single shift en el comprador&apos;s site; 2,500&nbsp;m&sup2;/día rated en two shifts",ru:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/день на a single shift в the покупатель&apos;s site; 2,500&nbsp;m&sup2;/день rated на two shifts",ar:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/يوم على a single shift في the المشتري&apos;s site; 2,500&nbsp;m&sup2;/يوم rated على two shifts",tr:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/gün üzerinde bir single shift de the alıcı&apos;s site; 2,500&nbsp;m&sup2;/gün rated üzerinde two shifts",fr:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/jour sur un single shift à le acheteur&apos;s site; 2,500&nbsp;m&sup2;/jour rated sur two shifts",pt:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/dia em um single shift em o comprador&apos;s site; 2,500&nbsp;m&sup2;/dia rated em two shifts",hi:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/दिन पर एक single shift पर the खरीदार&apos;s site; 2,500&nbsp;m&sup2;/दिन rated पर two shifts",id:"<strong>Target output:</strong> 1,200&nbsp;m&sup2;/hari pada sebuah single shift di the pembeli&apos;s site; 2,500&nbsp;m&sup2;/hari rated pada two shifts"},
    "case.vietnam.config.li5": {en:"<strong>Control:</strong> Siemens PLC with 10-inch HMI, Vietnamese and English language packs",zh:"<strong>控制系统：</strong>西门子PLC配10英寸HMI，越南语和英语语言包",es:"<strong>Control:</strong> Siemens PLC con 10-inch HMI, Vietnamese y English language packs",ru:"<strong>Control:</strong> Siemens PLC с 10-inch HMI, Vietnamese и English language packs",ar:"<strong>Control:</strong> Siemens PLC مع 10-inch HMI, Vietnamese و English language packs",tr:"<strong>Control:</strong> Siemens PLC ile 10-inch HMI, Vietnamese ve English language packs",fr:"<strong>Control:</strong> Siemens PLC avec 10-inch HMI, Vietnamese et English language packs",pt:"<strong>Control:</strong> Siemens PLC com 10-inch HMI, Vietnamese e English language packs",hi:"<strong>Control:</strong> Siemens PLC के साथ 10-inch HMI, Vietnamese और English language packs",id:"<strong>Control:</strong> Siemens PLC dengan 10-inch HMI, Vietnamese dan English language packs"},
    "case.vietnam.config.li6": {en:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",zh:"<strong>电源：</strong>380V三相50Hz（匹配越南电网）",es:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",ru:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",ar:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",tr:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",fr:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",pt:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",hi:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)",id:"<strong>Power:</strong> 380V 3-phase 50Hz (matching Vietnamese mains supply)"},
    "case.vietnam.config.li7": {en:"<strong>Options:</strong> TDF flange forming in-line, beading and notching, integrated decoiler with electric braking",zh:"<strong>选配：</strong>在线TDF法兰成型、压筋和切角、电动制动集成开卷机",es:"<strong>Options:</strong> brida TDF forming in-line, beading y notching, integrated desbobinadora con electric braking",ru:"<strong>Options:</strong> TDF фланец forming in-line, beading и notching, integrated размотчик с electric braking",ar:"<strong>Options:</strong> شفة TDF forming in-line, beading و notching, integrated فاتح اللفات مع electric braking",tr:"<strong>Options:</strong> TDF flanş forming in-line, beading ve notching, integrated açıcı ile electric braking",fr:"<strong>Options:</strong> bride TDF forming in-line, beading et notching, integrated dérouleur avec electric braking",pt:"<strong>Options:</strong> flange TDF forming in-line, beading e notching, integrated desbobinadora com electric braking",hi:"<strong>Options:</strong> TDF फ्लैंज forming in-line, beading और notching, integrated डिकॉइलर के साथ electric braking",id:"<strong>Options:</strong> flensa TDF forming in-line, beading dan notching, integrated decoiler dengan electric braking"},
