    "cat.cuttingandforming.h3_12": { en: "Nail-free Riveting Machine F350", zh: "无铆钉铆接机 F350", es: "Remachadora sin remaches F350", ru: "Станок клепки без заклёпок F350", ar: "آلة التبرشم بدون مسامير F350", tr: "Çivisiz perçinleme makinesi F350", fr: "Riveteuse sans rivet F350", pt: "Rebitadeira sem rebites F350", hi: "नेल-फ्री रिवेटिंग मशीन F350", id: "Mesin keling tanpa paku F350" },
    "cat.cuttingandforming.h3_13": { en: "Power Slitting & Beading Machine SBLQ-15", zh: "电动纵剪压筋机 SBLQ-15", es: "Máquina cortadora y estampadora SBLQ-15", ru: "Электрический станок для резки и зиговки SBLQ-15", ar: "آلة الشق والتحبيب الكهربائية SBLQ-15", tr: "Güç dilme ve boncuk makinesi SBLQ-15", fr: "Refendeuse-moulureuse électrique SBLQ-15", pt: "Máquina de corte e friso SBLQ-15", hi: "पावर स्लिटिंग और बीडिंग मशीन SBLQ-15", id: "Mesin pembelah & pembentuk alur SBLQ-15" },
